const input = $input.first().json;
const raw = input.categoria ? String(input.categoria).trim().toUpperCase() : '';
const cat = raw === 'ADULTOS' ? 'ADULTO' : raw;
const VALIDAS = ['KIDS', 'ADULTO', 'ADOLESCENTE', 'PERSONALIZADO', 'AU_PAIR'];

let query = `SELECT id, nombre, tipo, nivel, categoria, dia_1, dia_2,
       hora_inicio, hora_fin, cupo_max, cupo_actual, precio_mensual,
       descripcion, activo, created_at, updated_at
FROM horarios
WHERE activo = TRUE`;

if (cat && VALIDAS.includes(cat)) {
  query += ` AND categoria = '${cat}'`;
} else if (cat) {
  query += ` AND false`; // categoría desconocida: sin resultados (evita inyección)
}

query += ` ORDER BY nombre ASC;`;

return [{ json: { query, categoria: cat } }];

const cat = $('arma query').first().json.categoria || '';
const rows = $('obtener horarios').all()
  .map((row) => row.json)
  .filter((h) => h && h.id !== undefined && h.id !== null);

const horarios = rows.map((h) => ({
  ...h,
  ocupacion_porcentaje: h.cupo_max ? Math.round((h.cupo_actual / h.cupo_max) * 100) : null,
  cupos_libres: h.cupo_max !== null && h.cupo_max !== undefined ? h.cupo_max - h.cupo_actual : null
}));

const compacto = (h) => ({
  nombre: h.nombre, categoria: h.categoria, tipo: h.tipo, nivel: h.nivel,
  dia_1: h.dia_1, dia_2: h.dia_2, hora_inicio: h.hora_inicio, hora_fin: h.hora_fin,
  cupos_libres: h.cupos_libres
});
const disponibles = horarios.filter((h) => h.cupos_libres === null || h.cupos_libres > 0).map(compacto);
const completos = horarios.filter((h) => h.cupos_libres !== null && h.cupos_libres <= 0).map(compacto);

let nota = '';
if (horarios.length === 0) {
  if (cat === 'PERSONALIZADO' || cat === 'AU_PAIR') {
    nota = 'Las clases personalizadas y de Au Pair no tienen grilla fija: los días y horarios se coordinan a medida con Fla. NO confirmes días ni horas ni reserves nada; pedile su disponibilidad y avisale a Fla con solicitar-contacto-fla.';
  } else {
    nota = 'No hay horarios abiertos para esta categoría por ahora (los horarios se abren según la demanda). NO inventes horarios; pedile su disponibilidad y avisale a Fla con solicitar-contacto-fla.';
  }
} else if (disponibles.length === 0) {
  nota = 'Los horarios abiertos de esta categoría están todos completos. NO ofrezcas ninguno ni anotes a nadie: avisale a Fla con solicitar-contacto-fla (ella maneja la lista de espera).';
} else {
  nota = 'Ofrecé SOLO los de "disponibles" (tienen cupos libres), con sus días y horas exactos.' +
    (completos.length ? ' Los de "completos" NO los ofrezcas.' : '') +
    ' No confirmes ni inventes ningún otro día u hora, y no digas que reservaste: el lugar queda definitivamente reservado recién cuando se realiza el pago. Los horarios se abren según la demanda: si ninguno le sirve, avisale a Fla con solicitar-contacto-fla.';
}

return [{ json: { success: true, total: horarios.length, disponibles, completos, items: horarios, nota } }];
